pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        address revertContract = address(new AlwaysRevert());
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = from;

        vm.prank(from);
        bool ok;
        try c.transfer(from, revertContract, tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract AlwaysRevert {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}
